/* B 端共享框架：布局一致，平台申请与组织运营仍分别校验身份和用途。 */
const BShell=(()=>{
 const {icon:I}=UI;
 function render({body,sidebar,context,tools='',active='',approved=false,note='',prototype='界面原型 · 虚构数据 · 不发生真实业务操作'}){
 document.getElementById('app').innerHTML=`<button class="b-nav-backdrop" aria-label="关闭侧栏" data-bshell="menu-close" hidden></button><aside class="sidebar" id="b-sidebar">${UI.brand().replace('href="index.html#home"','href="organizer.html#apply"')}${sidebar}<div class="sidebar-bottom"><span class="sidebar-city">${I('pin')} 保定城市站</span><br>${context}<a href="index.html#home">${I('user')} 返回运动者界面</a></div></aside><header class="b-top"><div class="row"><button class="btn text b-menu" data-bshell="menu" aria-label="打开工作台导航" aria-controls="b-sidebar" aria-expanded="false">${I('settings')}</button><span class="muted small">平台工作台</span>${I('chevron')}<strong class="small">${context}</strong></div><div class="page-tools"><a class="btn" href="index.html#home">${I('user')} 运动者身份</a>${tools}<span class="avatar">林</span></div></header><nav class="b-route-tabs" aria-label="B端页面切换"><a href="organizer.html#apply" class="${active==='apply'?'active':''}" ${active==='apply'?'aria-current="page"':''}>办赛申请</a><a href="organizer.html#status" class="${active==='status'?'active':''}" ${active==='status'?'aria-current="page"':''}>审核进度与记录</a>${approved?`<a href="business.html#workspace/overview" class="${active==='business'?'active':''}" ${active==='business'?'aria-current="page"':''}>赛事运营</a>`:`<span aria-disabled="true" title="准入通过并取得有效组织授权后开放">${I('lock')} 赛事运营 · 准入后开放</span>`}</nav><div class="proto"><span>${prototype}</span></div><main class="b-main ${active==='business'?'':'org-content'}" id="main">${body}${note?`<p class="route-note">${note}</p>`:''}</main>`;
 }
 function menu(open){document.getElementById('b-sidebar')?.classList.toggle('open',open);const backdrop=document.querySelector('.b-nav-backdrop');if(backdrop)backdrop.hidden=!open;const button=document.querySelector('[data-bshell="menu"]');if(button){button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'关闭工作台导航':'打开工作台导航')}}
 document.addEventListener('click',e=>{const action=e.target.closest('[data-bshell]')?.dataset.bshell;if(action==='menu')menu(!document.getElementById('b-sidebar')?.classList.contains('open'));if(action==='menu-close')menu(false)});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu(false);document.querySelector('.drawer [data-action="close-drawer"]')?.click()}});
 return {render};
})();
